-- Catalogue MatchTrip exporté de l'ancienne base Supabase (matchtrip_fixtures, matchtrip_club_media, matchtrip_catalog_config).
-- Rejouable : met à jour les lignes existantes sans rien supprimer. À appliquer après le schéma :
--   mariadb matches < server/seed.sql

SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE country = VALUES(country), zone = VALUES(zone), cluster = VALUES(cluster), city = VALUES(city), league = VALUES(league), home = VALUES(home), away = VALUES(away), date = VALUES(date), time = VALUES(time), provisional = VALUES(provisional), highlight = VALUES(highlight), source_url = VALUES(source_url), date_window_start = VALUES(date_window_start), date_window_end = VALUES(date_window_end), created_at = VALUES(created_at), updated_at = VALUES(updated_at), date_confirmed = VALUES(date_confirmed), time_confirmed = VALUES(time_confirmed), verified_source_url = VALUES(verified_source_url), verified_at = VALUES(verified_at), venue_override = VALUES(venue_override), venue_source_url = VALUES(venue_source_url), venue_confirmed = VALUES(venue_confirmed);

ON DUPLICATE KEY UPDATE logo_url = VALUES(logo_url), club_source_url = VALUES(club_source_url), stadium = VALUES(stadium), stadium_image_url = VALUES(stadium_image_url), stadium_source_url = VALUES(stadium_source_url), stadium_official_url = VALUES(stadium_official_url), verified_at = VALUES(verified_at), ticket_url = VALUES(ticket_url), ticket_source_url = VALUES(ticket_source_url), ticket_checked_at = VALUES(ticket_checked_at), stadium_image_page_url = VALUES(stadium_image_page_url), stadium_image_license = VALUES(stadium_image_license), stadium_image_author = VALUES(stadium_image_author), media_checked_at = VALUES(media_checked_at), ticket_kind = VALUES(ticket_kind);

ON DUPLICATE KEY UPDATE value = VALUES(value), updated_at = VALUES(updated_at);
